// spec v1.12 round-13 merge: Miniflare local D1 row-count check (npm i miniflare; node <file>). Prints meta.rows_read / rows_written per statement.
import { Miniflare } from "miniflare";
const mf = new Miniflare({ modules:true, script:"export default {fetch(){return new Response('x')}}", d1Databases:{DB:"db13"} });
const db = await mf.getD1Database("DB");
const q = async (label, sql, ...b) => { const r = await db.prepare(sql).bind(...b).all(); console.log(label.padEnd(40), "read", r.meta.rows_read, "written", r.meta.rows_written, "changes", r.meta.changes, "n", r.results.length, r.results.length&&label.startsWith("EQP")?JSON.stringify(r.results.map(x=>x.detail)):""); return r; };
await db.exec("CREATE TABLE auth_attempts (id INTEGER PRIMARY KEY, key_u TEXT NOT NULL, key_ip TEXT NOT NULL, at INTEGER NOT NULL)");
await db.exec("CREATE INDEX auth_attempts_u ON auth_attempts(key_u, at)");
await db.exec("CREATE INDEX auth_attempts_ip ON auth_attempts(key_ip, at)");
const now=100_000_000, M=60_000; const st=[];
for (const m of [46,31,30,29,1]) for (let i=0;i<100;i++) st.push(db.prepare("INSERT INTO auth_attempts(key_u,key_ip,at) VALUES(?,?,?)").bind("u"+m+"_"+i,"ip"+i,now-m*M));
await db.batch(st);
await q("AL-12 cron DELETE (500 rows)", "DELETE FROM auth_attempts WHERE at < ?", now-30*M);
await q("AL-12 cron DELETE again (no expired)", "DELETE FROM auth_attempts WHERE at < ?", now-30*M);
// records schema per D-59
await db.exec(`CREATE TABLE records(id TEXT PRIMARY KEY, kind TEXT NOT NULL DEFAULT '', part TEXT NOT NULL DEFAULT '', rev TEXT NOT NULL DEFAULT '', lot TEXT NOT NULL DEFAULT '', side TEXT NOT NULL DEFAULT '', vendor TEXT NOT NULL DEFAULT '', place_id TEXT NOT NULL DEFAULT '', name TEXT, user TEXT, created INTEGER, bytes INTEGER, gz_bytes INTEGER, sha256 TEXT NOT NULL DEFAULT '', meta TEXT)`);
await db.exec("CREATE UNIQUE INDEX r_u ON records(kind,part,rev,lot,side,vendor,place_id,sha256)");
await db.exec("CREATE INDEX r_k ON records(kind, created DESC, id DESC)");
await db.exec("CREATE INDEX r_sha ON records(sha256)");
await q("records INSERT", "INSERT INTO records(id,kind,lot,created,sha256) VALUES('a','meas','L',1,'h') ON CONFLICT(id) DO NOTHING");
await q("records INSERT conflict", "INSERT INTO records(id,kind,lot,created,sha256) VALUES('a','meas','L',1,'h') ON CONFLICT(id) DO NOTHING");
await q("records DELETE 1", "DELETE FROM records WHERE id='a'");
await db.exec("CREATE TABLE audit_log(seq INTEGER PRIMARY KEY, at INTEGER, by TEXT, action TEXT, target_type TEXT, target_id TEXT, detail TEXT, src_key TEXT)");
await db.exec("CREATE INDEX al_at ON audit_log(at DESC)"); await db.exec("CREATE INDEX al_t ON audit_log(target_id)");
await db.exec("CREATE UNIQUE INDEX audit_log_src ON audit_log(src_key) WHERE src_key IS NOT NULL");
await q("audit INSERT app (src NULL)", "INSERT INTO audit_log(at,by,action,target_id) VALUES(1,'u','create','x')");
await q("audit INSERT migr (src)", "INSERT INTO audit_log(at,by,action,target_id,src_key) VALUES(1,'migration','migrate_exclude','x','exclude:record:x') ON CONFLICT(src_key) WHERE src_key IS NOT NULL DO NOTHING");
await q("audit DELETE exclude row", "DELETE FROM audit_log WHERE src_key='exclude:record:x'");
await db.exec("CREATE TABLE shares(id TEXT PRIMARY KEY, user TEXT, name TEXT, created INTEGER, exp INTEGER, bytes INTEGER, revoked_at INTEGER, revoked_by TEXT)");
await db.exec("CREATE INDEX s_u ON shares(user, created DESC)"); await db.exec("CREATE INDEX s_e ON shares(exp)");
await q("shares INSERT", "INSERT INTO shares VALUES('s1','u','n',1,2,3,NULL,NULL)");
await q("shares DELETE", "DELETE FROM shares WHERE id='s1'");
await q("EQP all=1 p1", "EXPLAIN QUERY PLAN SELECT * FROM shares ORDER BY created DESC, id DESC LIMIT 51");
await q("EQP all=1 p2", "EXPLAIN QUERY PLAN SELECT * FROM shares WHERE (created,id)<(?,?) ORDER BY created DESC, id DESC LIMIT 51", 5, "x");
await q("EQP mine=1 p2", "EXPLAIN QUERY PLAN SELECT * FROM shares WHERE user=? AND (created,id)<(?,?) ORDER BY created DESC, id DESC LIMIT 51", "u", 5, "x");
await q("EQP mine=1 p1", "EXPLAIN QUERY PLAN SELECT * FROM shares WHERE user=? ORDER BY created DESC, id DESC LIMIT 51", "u");
await q("EQP retention all kinds", "EXPLAIN QUERY PLAN SELECT id FROM records WHERE created<? LIMIT 40", 5);
await q("EQP retention per kind", "EXPLAIN QUERY PLAN SELECT id FROM records WHERE kind=? AND created<? ORDER BY created LIMIT 40", "meas", 5);
await q("EQP records p2", "EXPLAIN QUERY PLAN SELECT id FROM records WHERE kind=? AND (created,id)<(?,?) ORDER BY created DESC, id DESC LIMIT 51","meas",5,"x");
await mf.dispose();
